solution.jsx:
function MovieList({ movies }) {
  if (movies.length === 0) {
    return <p>Nothing to watch yet.</p>;
  }

  return (
    <ul>
      {movies.map((movie) => (
        <li key={movie.id}>
          {movie.title}
          {movie.watched && <span className="badge">Watched</span>}
        </li>
      ))}
    </ul>
  );
}

const MOVIES = [
  { id: 1, title: 'Arrival', watched: true },
  { id: 2, title: 'Past Lives', watched: false },
  { id: 3, title: 'Paddington 2', watched: false },
];

export default function App() {
  return (
    <main>
      <section id="full">
        <MovieList movies={MOVIES} />
      </section>
      <section id="empty">
        <MovieList movies={[]} />
      </section>
    </main>
  );
}
